 * @param {boolean[]} online
 * @param {number} k
 * @return {number}
 */
var findMaxPathScore = function(edges, online, k) {
    const n = online.length;
    const arr = Array.from({ length: n }, () => new Map());

    for (const [u, v, cost] of edges) {
        if (online[u]) {
            arr[u].set(v, cost);
        }
    }

    let stack = [[0, 0, Infinity]];
    let res = -Infinity;

    while (stack.length > 0) {
        const next = [];

        for (const [node, cost, min] of stack) {
            if (node === n - 1) {
                res = Math.max(res, min);
                continue;
            }

            for (const [con, edge] of arr[node]) {
                const cc = cost + edge;
                if (cc <= k) {
                    next.push([con, cc, Math.min(min, edge)]);
                }
            }
        }

        stack = next;
    }

    return res === -Infinity ? -1 : res;
};

